(6942399, 1046505, 142273, '<td valign="top">Liked the mood to it! Great!</td>', 'Liked the mood to it! Great!', '2012-12-27 01:00:14.000000', NULL, 1),
(6942665, 1046189, 78196, '<td valign="top">This is nicely brooding and unsettling.  For me, the bright light in the bottom left is a bit of a distraction.  The high noise, lack of detail and your choice of composition all effective.</td>', 'This is nicely brooding and unsettling.  For me, the bright light in the bottom left is a bit of a distraction.  The high noise, lack of detail and your choice of composition all effective.', '2012-12-27 13:50:19.000000', NULL, 1),
(6942666, 1046503, 78196, '<td valign="top">I want the sky to be lighter, but then I guess you''re in danger of not meeting the challenge... Nicely composed &amp; good PS work on the trees.</td>', 'I want the sky to be lighter, but then I guess you''re in danger of not meeting the challenge... Nicely composed & good PS work on the trees.', '2012-12-27 13:51:20.000000', NULL, 1),
(6942667, 1046490, 78196, '<td valign="top">Clever idea, I didn''t see the silhouettes at first.  Pleasingly festive :)</td>', 'Clever idea, I didn''t see the silhouettes at first.  Pleasingly festive :)', '2012-12-27 13:52:09.000000', NULL, 1),
(6942668, 1046428, 78196, '<td valign="top">Clever idea, well executed and composed.</td>', 'Clever idea, well executed and composed.', '2012-12-27 13:52:48.000000', NULL, 1),
(6942669, 1046382, 78196, '<td valign="top">Great fun.  The execution &amp; processing could hardly be better.</td>', 'Great fun.  The execution & processing could hardly be better.', '2012-12-27 13:53:36.000000', NULL, 1),
(6942670, 1046456, 78196, '<td valign="top">Nice candid-style shot that meets the challenge perfectly.</td>', 'Nice candid-style shot that meets the challenge perfectly.', '2012-12-27 13:54:25.000000', NULL, 1),
(6942671, 1046431, 78196, '<td valign="top">This is great.  Love the simplicity of the bold colours and contrast.  Just wish the boy on the right didn''t have his hand cut off, though this is a minor detail.</td>', 'This is great.  Love the simplicity of the bold colours and contrast.  Just wish the boy on the right didn''t have his hand cut off, though this is a minor detail.', '2012-12-27 13:56:25.000000', NULL, 1),
(6942673, 1046513, 78196, '<td valign="top">Imaginative idea, perfectly executed.</td>', 'Imaginative idea, perfectly executed.', '2012-12-27 13:57:31.000000', NULL, 1),
(6942675, 1046345, 78196, '<td valign="top">This is fantastic.  You''ve captured a real sense of vulnerability here and combined it with brilliant control of light and perfect post-processing. It''s a ten from me and I hope others follow.</td>', 'This is fantastic.  You''ve captured a real sense of vulnerability here and combined it with brilliant control of light and perfect post-processing. It''s a ten from me and I hope others follow.', '2012-12-27 14:00:20.000000', NULL, 1),
(6942678, 1046526, 78196, '<td valign="top">Daringly ambiguous.  Really like this kind of image.</td>', 'Daringly ambiguous.  Really like this kind of image.', '2012-12-27 14:02:41.000000', NULL, 1),
(6942680, 1046508, 78196, '<td valign="top">Well controlled image, great colour &amp; composition, but I imagine you''ll be marked down if the sun is above the horizon!</td>', 'Well controlled image, great colour & composition, but I imagine you''ll be marked down if the sun is above the horizon!', '2012-12-27 14:03:28.000000', NULL, 1),
(6942682, 1046448, 78196, '<td valign="top">I have no idea how you did this but I love it.  Would like to see how it looks with the walker slightly off-centre.  Wonderfully imaginative.</td>', 'I have no idea how you did this but I love it.  Would like to see how it looks with the walker slightly off-centre.  Wonderfully imaginative.', '2012-12-27 14:04:38.000000', NULL, 1),
(6942683, 1046525, 78196, '<td valign="top">Exposure and PP absolutely spot-on.  Love the detail in the sky.</td>', 'Exposure and PP absolutely spot-on.  Love the detail in the sky.', '2012-12-27 14:05:10.000000', NULL, 1),
(6942684, 1046170, 78196, '<td valign="top">That''s some control of light.  Bride looks like something out of a Tim Burton movie (in a good way).  Great entry.</td>', 'That''s some control of light.  Bride looks like something out of a Tim Burton movie (in a good way).  Great entry.', '2012-12-27 14:06:06.000000', NULL, 1),
(6942687, 1046326, 78196, '<td valign="top">This has the most tremendous energy, a very exciting image.</td>', 'This has the most tremendous energy, a very exciting image.', '2012-12-27 14:06:53.000000', NULL, 1),
(6942688, 1046487, 78196, '<td valign="top">This is wonderful.  Light is beautifully controlled.  Promise me you''ll do a version with those legs edited out ;)</td>', 'This is wonderful.  Light is beautifully controlled.  Promise me you''ll do a version with those legs edited out ;)', '2012-12-27 14:08:08.000000', NULL, 1),
(6942689, 1046254, 78196, '<td valign="top">Well composed and edited. Not quite enough emotional interest from the guy on the right, but I guess that''s his fault ;)</td>', 'Well composed and edited. Not quite enough emotional interest from the guy on the right, but I guess that''s his fault ;)', '2012-12-27 14:09:23.000000', NULL, 1),
(6942690, 1046466, 78196, '<td valign="top">Cheesy but nice, and very well executed.</td>', 'Cheesy but nice, and very well executed.', '2012-12-27 14:10:05.000000', NULL, 1),
(6942693, 1046527, 78196, '<td valign="top">Great fun &amp; the PP is spot-on</td>', 'Great fun & the PP is spot-on', '2012-12-27 14:12:37.000000', NULL, 1),
(6942710, 1046431, 114225, '<td valign="top">I like the playfulness in this.</td>', 'I like the playfulness in this.', '2012-12-27 14:27:38.000000', NULL, 1),
(6942711, 1046466, 114225, '<td valign="top">Great idea and well posed.</td>', 'Great idea and well posed.', '2012-12-27 14:28:12.000000', NULL, 1),
(6942713, 1046505, 114225, '<td valign="top">Perfect execution of a great idea.</td>', 'Perfect execution of a great idea.', '2012-12-27 14:29:16.000000', NULL, 1),
(6942715, 1046382, 114225, '<td valign="top">Oooh, very menacing. Great use of noir.</td>', 'Oooh, very menacing. Great use of noir.', '2012-12-27 14:29:38.000000', NULL, 1),
