(6942722, 1046508, 114225, '<td valign="top">I wouldn''t exactly call this "at night" more like "after day break"</td>', 'I wouldn''t exactly call this "at night" more like "after day break"', '2012-12-27 14:40:32.000000', NULL, 1),
